// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(uint256 seed) public {
        // Derive a wide fuzzed domain of interface ids: seed 0 maps to the IERC165 id,
        // every other seed maps to an arbitrary id. The fuzzer searches the whole space.
        bytes4 interfaceId = type(IERC165).interfaceId ^ bytes4(uint32(seed));

        // General rule: the contract reports support exactly for the three interface ids
        // it implements (IERC165, IERC1155, IERC1155MetadataURI) and false for everything else.
        bool expected =
            interfaceId == type(IERC165).interfaceId ||
            interfaceId == type(IERC1155).interfaceId ||
            interfaceId == type(IERC1155MetadataURI).interfaceId;

        bool actual;
        try c.supportsInterface(interfaceId) returns (bool supported) {
            actual = supported;
        } catch {
            actual = false;
        }

        assertTrue(actual == expected);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }

    function testFuzz_property(address account, uint256 id) public {
        // Admissible domain: any account, any id (as owner) — wide domain.
        // General rule: balanceOf completes (does not revert) for any account;
        // but for the zero address it MUST revert. Equivalently:
        // for every (account, id), the call succeeds iff account != address(0).
        bool ok;
        uint256 bal;
        try c.balanceOf(account, id) returns (uint256 b) {
            ok = true;
            bal = b;
        } catch {
            ok = false;
        }

        // Single assertion: the call's completion status must match admissibility,
        // and when it completes for a non-zero account it must not be an
        // undefined zero-address read (zero address is rejected, never queried).
        assertTrue(
            (account == address(0)) ? !ok : (ok && bal == c.balanceOf(account, id)),
            "balanceOf must revert for the zero address and succeed otherwise"
        );
    }
}
